import json
raw = '{"seen": ["c1"], "schema_version": 2}'
progress = {}
if raw:
    try:
        progress = json.loads(raw)
    except json.JSONDecodeError:
        progress = {"recovery": True}
schema_version = progress["schema_version"]

def migrate_v1_to_v2(progress):
    migrated = dict(progress)
    migrated["schema_version"] = 2
    migrated["confused"] = []
    return migrated

progress = {"schema_version": 1, "seen": ["c1"]}
version = progress.get("schema_version", 1)
if version == 1:
    progress = migrate_v1_to_v2(progress)
final_version = progress["schema_version"]

local_storage = {"pythonReadingProgress": "saved-progress"}
confirmed = False
if confirmed:
    local_storage.pop("pythonReadingProgress", None)
progress_exists = "pythonReadingProgress" in local_storage

